uniform 	mediump vec4 _Color;
uniform 	vec4 _ClipRect;
uniform 	vec4 _MainTexConfig;
uniform 	vec4 _DissolveTillingSpeed;
uniform 	vec4 _DissolveMapA_ST;
uniform 	float _AmountA;
uniform 	float _BorderWidthA;
uniform 	vec4 _DissolveMapB_ST;
uniform 	float _AmountB;
uniform 	float _BorderWidthB;
UNITY_LOCATION(0) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(1) uniform mediump sampler2D _DissolveMapA;
UNITY_LOCATION(2) uniform mediump sampler2D _DissolveMapB;
in mediump vec4 vs_COLOR0;
in mediump vec2 vs_TEXCOORD0;
in highp vec4 vs_TEXCOORD1;
layout(location = 0) out mediump vec4 SV_Target0;
float u_xlat0;
bool u_xlatb0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec2 u_xlat2;
bvec2 u_xlatb2;
mediump float u_xlat16_3;
vec2 u_xlat4;
mediump float u_xlat16_4;
bvec2 u_xlatb4;
vec2 u_xlat8;
mediump float u_xlat16_8;
