{
    u_xlat0 = _AmountA * vs_COLOR0.x + 0.5;
    u_xlat0 = roundEven(u_xlat0);
    u_xlat0 = (-u_xlat0) + 1.0;
    u_xlat4.x = vs_COLOR0.x * _AmountA;
    u_xlat0 = u_xlat0 * _BorderWidthA + u_xlat4.x;
    u_xlat4.xy = vs_TEXCOORD0.xy * _DissolveMapA_ST.xy + _DissolveMapA_ST.zw;
    u_xlat4.xy = _Time.yy * _DissolveTillingSpeed.xy + u_xlat4.xy;
    u_xlat16_4 = texture(_DissolveMapA, u_xlat4.xy).x;
    u_xlat0 = (-u_xlat0) + u_xlat16_4;
    u_xlat0 = u_xlat0 / _BorderWidthA;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    u_xlat4.x = _AmountB * vs_COLOR0.y + 0.5;
    u_xlat4.x = roundEven(u_xlat4.x);
    u_xlat4.x = (-u_xlat4.x) + 1.0;
    u_xlat8.x = vs_COLOR0.y * _AmountB;
    u_xlat4.x = u_xlat4.x * _BorderWidthB + u_xlat8.x;
    u_xlat8.xy = vs_TEXCOORD0.xy * _DissolveMapB_ST.xy + _DissolveMapB_ST.zw;
    u_xlat8.xy = _Time.yy * _DissolveTillingSpeed.zw + u_xlat8.xy;
    u_xlat16_8 = texture(_DissolveMapB, u_xlat8.xy).x;
    u_xlat4.x = (-u_xlat4.x) + u_xlat16_8;
    u_xlat4.x = u_xlat4.x / _BorderWidthB;
    u_xlat4.x = clamp(u_xlat4.x, 0.0, 1.0);
    u_xlat0 = u_xlat4.x * u_xlat0;
    u_xlat4.xy = vs_TEXCOORD0.xy * _MainTexConfig.xy;
    u_xlat16_1 = texture(_MainTex, u_xlat4.xy);
    u_xlat0 = u_xlat0 * u_xlat16_1.w;
    u_xlat0 = clamp(u_xlat0, 0.0, 1.0);
    u_xlat1.xyz = u_xlat16_1.xyz * _Color.xyz;
    u_xlat0 = u_xlat0 * vs_COLOR0.w;
    u_xlatb4.xy = greaterThanEqual(vs_TEXCOORD1.xyxx, _ClipRect.xyxx).xy;
    u_xlat4.x = u_xlatb4.x ? float(1.0) : 0.0;
    u_xlat4.y = u_xlatb4.y ? float(1.0) : 0.0;
;
    u_xlatb2.xy = greaterThanEqual(_ClipRect.zwzz, vs_TEXCOORD1.xyxx).xy;
    u_xlat2.x = u_xlatb2.x ? float(1.0) : 0.0;
    u_xlat2.y = u_xlatb2.y ? float(1.0) : 0.0;
;
    u_xlat4.xy = u_xlat4.xy * u_xlat2.xy;
    u_xlat4.x = u_xlat4.y * u_xlat4.x;
    u_xlat16_3 = u_xlat0 * u_xlat4.x + -0.00100000005;
    u_xlat1.w = u_xlat4.x * u_xlat0;
    SV_Target0 = u_xlat1;
    u_xlatb0 = u_xlat16_3<0.0;
    if(u_xlatb0){discard;}
    return;
}

