#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	vec4 _Time;
uniform 	vec4 _AdditionRotateAnchorTime;
uniform 	vec4 _AddtionPannerSpeed;
uniform 	vec4 _AdditionMap_ST;
uniform 	float _OutStep;
uniform 	float _OutSmooth;
uniform 	float _InStep;
uniform 	float _InSmooth;
UNITY_LOCATION(0) uniform mediump sampler2D _AdditionMap;
in mediump vec4 vs_COLOR0;
in mediump vec2 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec4 u_xlat16_1;
vec2 u_xlat2;
vec2 u_xlat4;
void main()
{
    u_xlat0.xy = vs_TEXCOORD0.xy + vec2(-0.5, -0.5);
    u_xlat0.x = dot(u_xlat0.xy, u_xlat0.xy);
    u_xlat0.x = sqrt(u_xlat0.x);
    u_xlat0.xy = u_xlat0.xx + (-vec2(_OutStep, _InStep));
    u_xlat4.xy = vec2(1.0, 1.0) / (-vec2(_OutSmooth, _InSmooth));
    u_xlat0.xy = u_xlat4.xy * u_xlat0.xy;
    u_xlat0.xy = clamp(u_xlat0.xy, 0.0, 1.0);
    u_xlat4.xy = u_xlat0.xy * vec2(-2.0, -2.0) + vec2(3.0, 3.0);
    u_xlat0.xy = u_xlat0.xy * u_xlat0.xy;
    u_xlat2.x = u_xlat0.y * u_xlat4.y;
    u_xlat0.x = u_xlat4.x * u_xlat0.x + (-u_xlat2.x);
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat2.x = _Time.y * _AdditionRotateAnchorTime.z;
    u_xlat4.xy = vs_TEXCOORD0.xy * _AdditionMap_ST.xy + _AdditionMap_ST.zw;
    u_xlat2.xy = u_xlat2.xx * _AddtionPannerSpeed.xy + u_xlat4.xy;
    u_xlat16_1 = texture(_AdditionMap, u_xlat2.xy);
    u_xlat16_1.w = u_xlat0.x * u_xlat16_1.w;
    u_xlat0 = u_xlat16_1 * vs_COLOR0;
    SV_Target0 = u_xlat0;
    return;
}
